#include <algorithm>
#include <vector>

std::size_t lowerBound(const std::vector<int>& a, int x)
{
    std::size_t lo = 0, hi = a.size();
    while (lo < hi)
    {
        std::size_t mid = lo + (hi - lo) / 2;
        if (a[mid] < x) lo = mid + 1; else hi = mid;
    }
    return lo;
}

std::size_t upperBound(const std::vector<int>& a, int x)
{
    std::size_t lo = 0, hi = a.size();
    while (lo < hi)
    {
        std::size_t mid = lo + (hi - lo) / 2;
        if (a[mid] <= x) lo = mid + 1; else hi = mid;
    }
    return lo;
}

int searchRotated(const std::vector<int>& a, int x)
{
    int lo = 0, hi = static_cast<int>(a.size()) - 1;
    while (lo <= hi)
    {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == x) return mid;
        if (a[lo] <= a[mid])                       // the left half [lo, mid] is sorted
        {
            if (a[lo] <= x && x < a[mid]) hi = mid - 1; else lo = mid + 1;
        }
        else                                       // the right half [mid, hi] is sorted
        {
            if (a[mid] < x && x <= a[hi]) lo = mid + 1; else hi = mid - 1;
        }
    }
    return -1;
}

static bool canFinish(const std::vector<int>& piles, long long hours, long long speed)
{
    long long needed = 0;
    for (int p : piles)
    {
        needed += (p + speed - 1) / speed;
        if (needed > hours) return false;
    }
    return true;
}

long long minSpeed(const std::vector<int>& piles, long long hours)
{
    long long lo = 1, hi = 1;
    for (int p : piles) hi = std::max<long long>(hi, p);
    while (lo < hi)
    {
        long long mid = lo + (hi - lo) / 2;
        if (canFinish(piles, hours, mid)) hi = mid; else lo = mid + 1;
    }
    return lo;
}

unsigned long long sqrtFloor(unsigned long long n)
{
    unsigned long long lo = 0, hi = 4294967295ULL;     // the answer is in [lo, hi]
    while (lo < hi)
    {
        unsigned long long mid = lo + (hi - lo + 1) / 2;   // round up, so lo = mid always makes progress
        if (mid <= n / mid) lo = mid; else hi = mid - 1;
    }
    return lo;
}

