TEST("bounds") {
    std::vector<int> a{ 1, 3, 3, 3, 5, 8 };
    CHECK_EQ(lowerBound(a, 3), std::size_t{ 1 });
    CHECK_EQ(upperBound(a, 3), std::size_t{ 4 });
    CHECK_EQ(lowerBound(a, 4), std::size_t{ 4 });
    CHECK_EQ(upperBound(a, 4), std::size_t{ 4 });
    CHECK_EQ(lowerBound(a, 0), std::size_t{ 0 });
    CHECK_EQ(upperBound(a, 8), std::size_t{ 6 });
    CHECK_EQ(lowerBound({}, 5), std::size_t{ 0 });
}
TEST("bounds on 100,000 values") {
    std::vector<int> a(100000);
    for (int i = 0; i < 100000; ++i) a[i] = i / 2;          // each value twice
    long long total = 0;
    for (int x = 0; x < 50000; ++x) total += static_cast<long long>(upperBound(a, x) - lowerBound(a, x));
    CHECK_EQ(total, 100000LL);
}
TEST("rotated") {
    std::vector<int> a{ 15, 18, 22, 3, 5, 9, 12 };
    for (int i = 0; i < 7; ++i) CHECK_EQ(searchRotated(a, a[i]), i);
    CHECK_EQ(searchRotated(a, 4), -1);
    CHECK_EQ(searchRotated(a, 30), -1);
    CHECK_EQ(searchRotated({ 1, 2, 3 }, 3), 2);
    CHECK_EQ(searchRotated({ 2, 1 }, 1), 1);
    CHECK_EQ(searchRotated({}, 1), -1);
    std::vector<int> big(100000);
    for (int i = 0; i < 100000; ++i) big[i] = ((i + 61234) % 100000) * 3;
    bool all = true;
    for (int i = 0; i < 100000; i += 7) all = all && searchRotated(big, big[i]) == i;
    CHECK(all);
    CHECK_EQ(searchRotated(big, 1), -1);
}
TEST("eating speed") {
    CHECK_EQ(minSpeed({ 3, 6, 7, 11 }, 8), 4LL);
    CHECK_EQ(minSpeed({ 30, 11, 23, 4, 20 }, 5), 30LL);
    CHECK_EQ(minSpeed({ 30, 11, 23, 4, 20 }, 6), 23LL);
    CHECK_EQ(minSpeed({ 1000000000 }, 2), 500000000LL);
    CHECK_EQ(minSpeed({ 1, 1, 1 }, 1000), 1LL);
}
TEST("integer square roots") {
    CHECK_EQ(sqrtFloor(0), 0ULL);
    CHECK_EQ(sqrtFloor(1), 1ULL);
    CHECK_EQ(sqrtFloor(15), 3ULL);
    CHECK_EQ(sqrtFloor(16), 4ULL);
    CHECK_EQ(sqrtFloor(999999999999ULL), 999999ULL);
    CHECK_EQ(sqrtFloor(18446744073709551615ULL), 4294967295ULL);
    CHECK_EQ(sqrtFloor(18446744065119617025ULL), 4294967295ULL);   // exactly (2^32 - 1)^2
    CHECK_EQ(sqrtFloor(18446744065119617024ULL), 4294967294ULL);
}

